INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11601, 'Nehemiah 9:23', 'Nehemiah', 9, 23, '&nbsp;تا هغوئ له دومره بچى ورکړل لکه چې په آسمان کښې څومره ستورى دى، او تا هغوئ راوستل چې هغه مُلک قبضه کړى او هلته اوسيږى هغه مُلک کوم چې تا د هغوئ پلار نيکۀ له د ورکولو وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11602, 'Nehemiah 9:24', 'Nehemiah', 9, 24, '&nbsp;هغوئ د کنعان مُلک قبضه کړو، هلته چې کوم خلق اوسېدل تۀ په هغوئ باندې غالِب راغلې. تا خپلو خلقو له هغه طاقت ورکړو چې د هغوئ سره هغه شان کار وکړى چې څۀ يې خوښه وى څوک چې د کنعان بادشاهان او خلق وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11603, 'Nehemiah 9:25', 'Nehemiah', 9, 25, '&nbsp;ستا خلقو د پَخو دېوالونو ښارونه قبضه کړل، چې آباده زمکه، د دولت نه ډک کورونه ونيسى، هغه کوهى چې د مخکښې نه کنستلے شوى دى، د زيتُونو ونې، د مېوو ونې او د انګورو باغونه. هغوئ په مړه خېټه خوراک کولو او غټ شول، تا چې کوم ښۀ څيزونه هغوئ له ورکړى وُو د هغه هر څۀ نه يې خوند اخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11604, 'Nehemiah 9:26', 'Nehemiah', 9, 26, '&nbsp;خو ستا خلقو سرکشى وکړه او ستا نافرمانى يې وکړه، هغوئ ستا قانون ته شا کړه. هغوئ به هغه پېغمبران وژل چې خبردارے يې ورکولو، کومو چې ورته فرمائيل چې تا ته واپس راوګرځى. هغوئ ستا خِلاف لويه ګستاخى کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11605, 'Nehemiah 9:27', 'Nehemiah', 9, 27, '&nbsp;نو تا هغوئ خپلو دشمنانو ته حواله کړل. په خپلو تکليفونو کښې هغوئ تا ته د مدد دپاره چغه کړه، او په آسمان کښې تا د هغوئ فرياد واورېدو. د خپل لوئ رحم په وجه تا هغوئ له خلاصوونکى ورولېږل چا چې هغوئ د دشمنانو نه بچ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11606, 'Nehemiah 9:28', 'Nehemiah', 9, 28, '&nbsp;کله به چې خېر شو، نو هغوئ به ستا خِلاف بيا ګناه وکړه، او تا يو ځل بيا هغوئ دشمنانو ته حواله کړل. خو کله چې هغوئ توبه وويستله او سوال يې وکړو چې هغوئ بچ کړې، نو په آسمان کښې تا وخت په وخت د هغوئ سوال اورېدو او تا د خپل لوئ رحم په وجه هغوئ بچ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11607, 'Nehemiah 9:29', 'Nehemiah', 9, 29, '&nbsp;تا هغوئ له خبردارے ورکړو چې ستا قانون ته بيا راواپس شى، خو په غرور سره هغوئ ستا قانون و نۀ منلو، اګر چې ستا د قانون منل د ژوند لاره ده. هغه د سخت زړۀ او ضديانو خلقو نافرمانى وکړه او تا ته يې غوږ نۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11608, 'Nehemiah 9:30', 'Nehemiah', 9, 30, '&nbsp;ډېر کالونه تا هغوئ ته صبر کولو. تا د خپلو پېغمبرانو په ذريعه هغوئ له خبردارے ورکولو، خو ستا خلقو غوږ نۀ نيولو، نو تا هغوئ نورو قومونو ته حواله کړل چې فتح يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11609, 'Nehemiah 9:31', 'Nehemiah', 9, 31, '&nbsp;خو ستا د لوئ رحم په وجه، تا هغوئ نۀ پرېښودل او نۀ دې تباه کړل. تۀ رحمان او رحيم خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11610, 'Nehemiah 9:32', 'Nehemiah', 9, 32, '&nbsp;اے خُدايه پاکه، زمونږ خُدايه پاکه، تۀ څومره لوئ يې، تۀ څومره د رُعب والا او طاقتور يې. تۀ په وفادارۍ سره خپل لوظ پوره کوې. د هغه وخت نه کله چې د اسور بادشاهانو په مونږ ظلم کولو، تر اوسه پورې، مونږ څومره کړېدلى يُو. زمونږ بادشاهان، زمونږ مشران، زمونږ اِمامان او زمونږ پېغمبران، زمونږ پلار نيکۀ او زمونږ ټول خلق کړېدلى دى. مونږ چې څومره کړېدلى يُو نو هغه مۀ هېروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11611, 'Nehemiah 9:33', 'Nehemiah', 9, 33, '&nbsp;تا ښۀ وکړل چې مونږ له دې سزا راکړه، اګر چې مونږ ګناه هم کړې ده، خو تا مونږ سره اِنصاف وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11612, 'Nehemiah 9:34', 'Nehemiah', 9, 34, '&nbsp;زمونږ بادشاهانو، زمونږ مشرانو او زمونږ اِمامانو، زمونږ پلار نيکۀ ستا قانون نۀ دے منلے. هغوئ ستا قانون او خبردارى ته غوږ نۀ نيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11613, 'Nehemiah 9:35', 'Nehemiah', 9, 35, '&nbsp;کۀ څۀ هم چې د هغوئ په بادشاهۍ کښې تا هغوئ له لوئ برکت ورکړے وو، کله چې هغوئ په هغه کولاو او آباد مُلک کښې اوسېدل کوم چې تا هغوئ له ورکړے وو، خو بيا هم هغوئ د ګناه نه راونۀ ګرځېدل او نۀ يې ستا خِدمت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11614, 'Nehemiah 9:36', 'Nehemiah', 9, 36, '&nbsp;نو مونږ تر اوسه په هغه مُلک کښې غلامان يُو چې تا زمونږ پلار نيکۀ له ورکړے وو، چې د هغې په مېوه او پېداوار باندې مزې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11615, 'Nehemiah 9:37', 'Nehemiah', 9, 37, '&nbsp;چې زمکه څۀ پېدا کوى نو هغه بادشاهانو له ځى چې زمونږ د ګناه په وجه تا په مونږ باندې مقرر کړى دى. هغوئ زمونږ او زمونږ د څاروو سره هغه څۀ کوى چې څۀ يې خوښه وى، او مونږ په يوه سخته پرېشانۍ کښې يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11616, 'Nehemiah 9:38', 'Nehemiah', 9, 38, '&nbsp;”چې دا هر څۀ شوى دى نو مونږ بنى اِسرائيليان دا پخه ليکلې معاهده کوُو او زمونږ مشران، ليويان او زمونږ اِمامان به په دې باندې خپل مهرونه ولګوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11617, 'Nehemiah 10:1', 'Nehemiah', 10, 1, '&nbsp;کومو کسانو چې دستخطونه وکړل هغوئ دا وُو: د حکلياه زوئ نحمياه حکمران. صدقياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11618, 'Nehemiah 10:28', 'Nehemiah', 10, 28, '&nbsp;مونږ يعنې بنى اِسرائيلو، اِمامانو، ليويانو، څوکيدارانو، سندرغاړو، د خُدائ پاک د کور خِدمتګارانو او هغه نورو ټولو خلقو د خُدائ پاک د قانون د تابعدارۍ په بنياد خپل ځانونه د پردى مُلک د هغه خلقو نه جدا کړى وُو کوم چې زمونږ په مُلک کښې اوسېدل. مونږ د خپلو ښځو او د هغه ټولو بچو سره د کومو عُمر چې پوهېدو ته رسېدلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11619, 'Nehemiah 10:29', 'Nehemiah', 10, 29, '&nbsp;مونږ د خپلو مشرانو سره په يو قسم کولو کښې شريک شُو او ومو وئيل چې مونږ کۀ قسم مات کړو نو په مونږ دې لعنت وى او دا چې مونږ به د خُدائ پاک د قانون په مطابق خپل ژوند تېروو، هم هغه قانون کوم چې خُدائ پاک د خپل خِدمت کوونکى موسىٰ په ذريعه راکړے وو، چې مونږ به هغه هر څۀ منو چې مالِک خُدائ زمونږ خُدائ پاک يې حُکم راکوى، او چې مونږ به د هغۀ ټول قانون او اصُول منو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11620, 'Nehemiah 10:30', 'Nehemiah', 10, 30, '&nbsp;مونږ دا وعده وکړه چې د هغه مُلک د غېرو قومونو خلقو له به خپلې لوڼه نۀ ورکوو او د هغوئ لوڼه به خپلو زامنو ته نۀ وادۀ کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11621, 'Nehemiah 10:31', 'Nehemiah', 10, 31, '&nbsp;کۀ د پردى مُلک خلق څۀ غله يا بل هر څيز هم د سبت يا په بله هره مقدسه ورځ په مونږ باندې د خرڅولو دپاره راوړى، نو مونږ به يې د هغوئ نه نۀ اخلو. په هر اوؤم کال به مونږ زمکه نۀ کرو او ټول قرضونه به معاف کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11622, 'Nehemiah 10:32', 'Nehemiah', 10, 32, '&nbsp;زمونږ هر يو کس به هر کال پينځۀ ګرامه سپين زر د خُدائ پاک د کور د خرچې دپاره په چنده کښې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11623, 'Nehemiah 10:33', 'Nehemiah', 10, 33, '&nbsp;مونږ به د خُدائ پاک د کور د عبادت دپاره د دې څيزونو بندوبست کوُو، مقدسه روټۍ، د هرې ورځې د غلې نذرانه، هغه ځناور چې هره ورځ د قربانۍ په توګه سوزولے شى، د سبت د ورځو، د نوې مياشتې د اختر او د نورو اخترونو دپاره مقدسې نذرانې، د بنى اِسرائيلو د ګناه کفارې دپاره نذرانې او هغه بل هر يو څيز چې د خُدائ پاک په کور کښې يې ضرورت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11624, 'Nehemiah 10:34', 'Nehemiah', 10, 34, '&nbsp;زمونږ خلق، اِمامان او ليويان به هر کال پچه اچوى چې دا معلومه کړى چې کومه يوه ډله د مالِک خُدائ زمونږ خُدائ پاک په قربان‌ګاه باندې د سوزولو دپاره لرګو بندوبست کوى او دا به د قانون په مطابق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11625, 'Nehemiah 10:35', 'Nehemiah', 10, 35, '&nbsp;مونږ به هر کال د خپل وړومبى رېبلے شوى فصل او زمونږ په ونو کښې د وړومبى پېدا شوې مېوې يوه نذرانه د مالِک خُدائ کور ته وړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11626, 'Nehemiah 10:36', 'Nehemiah', 10, 36, '&nbsp;زمونږ د هر يو کس وړومبے پېدا شوے زوئ به اِمامانو له د خُدائ پاک کور ته بوځُو او هلته به يې د خُدائ پاک د ښودلى شوى قانون په مطابق خُدائ پاک ته وقف کوُو. زمونږ د هر يو کس د غواګانو وړومبے پېدا شوے سخے او زمونږ د هر يو کس وړومبے پېدا شوے ګډُورے يا د چېلۍ بچے به هم وقف کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11627, 'Nehemiah 10:37', 'Nehemiah', 10, 37, '&nbsp;مونږ به هر کال اِمامانو له د خُدائ پاک کور ته د وړومبى رېبلى شوى فصل نه جوړې شوې پېړې او د انګورو د ميو خپلې نورې نذرانې، د زيتُونو تېل او هر قِسم مېوې هم وړُو. او مونږ به هغه هر څۀ نه لسمه حِصه ليويانو له راؤړو څۀ چې زمونږ په پټو کښې شوى دى، ځکه چې هغوئ زمونږ په کلو کښې د دې څيزونو د راټولو ذمه وار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11628, 'Nehemiah 10:38', 'Nehemiah', 10, 38, '&nbsp;کله چې لسمه حِصه راټولولے شى نو د هارون د اولاد اِمامان به ليويانو سره وى. او د هغه ټولې راټولې شوې لسمې حِصې نه به ليويان لسمه حِصه د خُدائ پاک د کور ګودامونو ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11629, 'Nehemiah 10:39', 'Nehemiah', 10, 39, '&nbsp;بنى اِسرائيل او ليويان به د فصل، ميو او د زيتُونو تېلو برخې هغه ګودامونو ته يوسى چرته چې د خُدائ پاک د کور سامان کېښودلے شى او چرته چې اِمامان، د دروازو څوکيداران او سندرغاړى حاضر وى. مونږ به زمونږ د خُدائ پاک د کور نه مخ نۀ اړوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11630, 'Nehemiah 11:1', 'Nehemiah', 11, 1, '&nbsp;مشران په يروشلم کښې دېره شول او باقى خلقو پچه واچوله چې د هر لسم خاندان نه يو خاندان خوښ کړى چې لاړ شى او د يروشلم په مقدس ښار کښې اوسيږى، خو هغه نور په خپلو ښارونو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11631, 'Nehemiah 11:2', 'Nehemiah', 11, 2, '&nbsp;خلقو د هغه ټولو خلقو دپاره برکت وغوښتو چې کوم په رضاکارانه توګه په يروشلم کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11632, 'Nehemiah 11:3', 'Nehemiah', 11, 3, '&nbsp;د يهوداه په ښارونو کښې بنى اِسرائيل، اِمامان، ليويان، د خُدائ پاک د کور کاريګران او د سليمان د نوکرانو اولاد په خپلو ښارونو کښې په خپلو جائيدادونو کښې اوسېدل. دا د يهوداه صُوبې د مشرانو ښاريانو تفصيل دے کوم چې په يروشلم کښې اوسېدل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11633, 'Nehemiah 11:4', 'Nehemiah', 11, 4, '&nbsp;د يهوداه قبيلې کسان دا دى: د زکرياه نمسے او د عُزياه زوئ عتاياه. د هغۀ په آباواجداد کښې امرياه، سفطياه او محلل‌اېل شامل وُو، چې د يهوداه زوئ د فارص اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11634, 'Nehemiah 11:5', 'Nehemiah', 11, 5, '&nbsp;او هم د کولحوزه نمسے او د باروک زوئ معسياه. د هغۀ په آباواجداد کښې حزاياه، عداياه، يويريب او زکرياه شامل وُو، چې د يهوداه د زوئ سيله اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11635, 'Nehemiah 11:6', 'Nehemiah', 11, 6, '&nbsp;د فارص د اولاد څلور سوه او اتۀ شپېتۀ ښۀ تکړه سړى په يروشلم کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11636, 'Nehemiah 11:7', 'Nehemiah', 11, 7, '&nbsp;د بنيامين د قبيلې کسان دا دى: د يوئيد نمسے او د مسلام زوئ سلو وو. د هغۀ په نورو آباواجداد کښې فداياه، قولاياه، معسياه، ايتى‌اېل او يشعياه شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11637, 'Nehemiah 11:8', 'Nehemiah', 11, 8, '&nbsp;د سلو نزدې خپلوان جبى او سلى وُو. ټول نهۀ سوه او اتۀويشت بنيامينيان په يروشلم کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11638, 'Nehemiah 11:9', 'Nehemiah', 11, 9, '&nbsp;د زِکرى زوئ يوايل د هغوئ مشر وو، د هسينوآه زوئ يهوداه په ښار کښې دوېم مشر آفسر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11639, 'Nehemiah 11:10', 'Nehemiah', 11, 10, '&nbsp;اِمامان: د يويريب زوئ يدعياه او يکين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11640, 'Nehemiah 11:11', 'Nehemiah', 11, 11, '&nbsp;شراياه زوئ د خِلقياه، زوئ د مسلام، زوئ د صدوق، زوئ د مرايوت، زوئ د اخيطوب، څوک چې د خُدائ پاک د کور مشر اِمام وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11641, 'Nehemiah 11:12', 'Nehemiah', 11, 12, '&nbsp;د دې قبيلې ټولو اتۀ سوه او دوويشتو کسانو د خُدائ پاک په کور کښې خِدمت کولو. د فللياه نمسے او د يروحام زوئ عداياه. د هغۀ په آباواجداد کښې امصى، زکرياه، فشحور او مُلکياه شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11642, 'Nehemiah 11:13', 'Nehemiah', 11, 13, '&nbsp;د هغۀ د قبيلې ټول دوه سوه او دوه څلوېښت کسان د کورَنو مشران وُو. د اخزائى نمسے او د عزراېل زوئ امشى. د هغۀ په آباواجداد کښې اِمير او مسلموت شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11643, 'Nehemiah 11:14', 'Nehemiah', 11, 14, '&nbsp;د هغۀ د قبيلې يو سل او اتۀويشت کسان ښۀ تکړه فوجيان وُو. د هغوئ مشر زبدى‌اېل وو چې د هجدوليم زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11644, 'Nehemiah 11:15', 'Nehemiah', 11, 15, '&nbsp;ليويان: د عزريقام نمسے او د حسوب زوئ سمعياه. د هغۀ په آباواجداد کښې حسبياه او بُنى شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11645, 'Nehemiah 11:16', 'Nehemiah', 11, 16, '&nbsp;سبتى او يوزبد، د خُدائ پاک د کور نه د بهر کار مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11646, 'Nehemiah 11:17', 'Nehemiah', 11, 17, '&nbsp;د زبدى نمسے او د ميکا زوئ متنياه چې د آسف د اولاد نه وو. هغۀ د خُدائ پاک په کور کښې د عبادت په وخت کښې د حمد‌و‌ثناء رهنمائى کوله. او بقبوقياه په متنياه پسې دوېم سړ‌ے وو. د جلال نمسے او د سموع زوئ عبدا د يدوتون د اولاد نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11647, 'Nehemiah 11:18', 'Nehemiah', 11, 18, '&nbsp;د يروشلم په مقدس ښار کښې ټول دوه سوه او څلور اتيا ليويان اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11648, 'Nehemiah 11:19', 'Nehemiah', 11, 19, '&nbsp;د خُدائ پاک د کور څوکيداران: عقوب، طلمون او د هغوئ خپلوان، ټول يو سل او دوه اويا کسان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11649, 'Nehemiah 11:20', 'Nehemiah', 11, 20, '&nbsp;نور بنى اِسرائيليان او پاتې اِمامان او ليويان د يهوداه په ښارونو کښې په خپلو خپلو جائيدادونو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11650, 'Nehemiah 11:21', 'Nehemiah', 11, 21, '&nbsp;د خُدائ پاک د کور خِدمتګاران د يروشلم په هغه برخه کښې اوسېدل چې نوم يې عوفل وو او هغوئ د ضيحا او جِسفا د مشرۍ لاندې کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11651, 'Nehemiah 11:22', 'Nehemiah', 11, 22, '&nbsp;د ليويانو هغه مشر چې په يروشلم کښې اوسېدو هغه د حسبياه نمسے او د بانى زوئ عُزى وو. د هغۀ په پلارانو نيکونو کښې متنياه او ميکا شامل وُو او هغه د آسف د قبيلې نه وو. دا هغه ډله وه چې د دې کسان د خُدائ پاک په کور کښې د موسيقۍ ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11652, 'Nehemiah 11:23', 'Nehemiah', 11, 23, '&nbsp;د دې دپاره شاهى اصُول مقرر وُو چې قبيلې به هره ورځ د خُدائ پاک د کور په موسيقۍ کښې مشرى څنګه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11653, 'Nehemiah 11:24', 'Nehemiah', 11, 24, '&nbsp;د يهوداه قبيلې د زارح د قبيلې د مشيزب‌ايل زوئ فتحياه د فارس په دربار کښې د بنى اِسرائيلو نمائندګى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11654, 'Nehemiah 11:25', 'Nehemiah', 11, 25, '&nbsp;ډېر خلق د خپلو پټو سره نزدې په کلو کښې اوسېدل. څۀ کسان چې د يهوداه د قبيلې وُو نو هغوئ په قِريَت‌اربع، ديبون، يقبضى‌اېل او د دې ښارونو سره نزدې کلو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11655, 'Nehemiah 11:26', 'Nehemiah', 11, 26, '&nbsp;هغوئ د يشوَع، مولاده او بيت‌فِلِط په ښارونو کښې هم اوسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11656, 'Nehemiah 11:27', 'Nehemiah', 11, 27, '&nbsp;او داسې په حصارسعول، بيرسبع او د دې نه ګېرچاپېره کلو کښې هم اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11657, 'Nehemiah 11:28', 'Nehemiah', 11, 28, '&nbsp;هغوئ د صِقلاج په ښار کښې، مقوناه او د دې نه ګېرچاپېره کلو کښې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11658, 'Nehemiah 11:29', 'Nehemiah', 11, 29, '&nbsp;په عين رِمون، صُرعا، يرموت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11659, 'Nehemiah 11:30', 'Nehemiah', 11, 30, '&nbsp;په زنوح، عدولام او نزدې کلو کښې اوسېدل. هغوئ په لکيس او په نزدې پټو کښې او په عزيقه او د دې په کلو کښې اوسېدل. نو د يهوداه خلق د بيرسبع نه واخله د هنوم وادۍ پورې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11660, 'Nehemiah 11:31', 'Nehemiah', 11, 31, '&nbsp;د بنيامين قبيلې خلق په دې ځايونو کښې اوسېدل، جبعه، مِکماس، عياه، بيت‌ايل او د دې نزدې کلو کښې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11661, 'Nehemiah 11:32', 'Nehemiah', 11, 32, '&nbsp;په عنتوت، نوب، عننياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11662, 'Nehemiah 11:33', 'Nehemiah', 11, 33, '&nbsp;حصور، راما، جيتم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11663, 'Nehemiah 11:34', 'Nehemiah', 11, 34, '&nbsp;حاديد، صبوئيم، نبلا‌ط،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11664, 'Nehemiah 11:35', 'Nehemiah', 11, 35, '&nbsp;لد، اونو او په هغه وادۍ کښې چې چرته کاريګر اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11665, 'Nehemiah 11:36', 'Nehemiah', 11, 36, '&nbsp;د ليويانو څۀ قبيلې کومې چې د يهوداه په علاقه کښې اوسېدلې وې هغوئ د بنيامين د خلقو سره اوسېدو دپاره ولېږل شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11666, 'Nehemiah 12:1', 'Nehemiah', 12, 1, '&nbsp;دا د هغه اِمامانو او ليويانو تفصيل دے کوم چې د شلتى‌اېل زوئ زرُبابل او د مشر اِمام يشوَع سره د جلاوطنۍ نه راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11667, 'Nehemiah 12:8', 'Nehemiah', 12, 8, '&nbsp;ليويان: دا کسان د شُکر ګزارۍ حمد‌و‌ثناء مشران وُو، يشوَع، بِنوئى، قدمى‌اېل، سربياه، يهوداه او متنياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11668, 'Nehemiah 12:9', 'Nehemiah', 12, 9, '&nbsp;دې کسانو ورسره آواز نيولو، بقبوقياه، عُنى او د هغوئ ملګرو ليويانو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11669, 'Nehemiah 12:10', 'Nehemiah', 12, 10, '&nbsp;يشوَع د يويقيم پلار وو، يويقيم د اِلياسب پلار وو، اِلياسب د يويدع پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11670, 'Nehemiah 12:11', 'Nehemiah', 12, 11, '&nbsp;يويدع د يونتن پلار وو، او يونتن د يدوع پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11671, 'Nehemiah 12:22', 'Nehemiah', 12, 22, '&nbsp;کله چې اِلياسب، يويدع، يوحانان او يدوع مشران اِمامان وُو نو د ليويانو د مشرانو فهرست تيار شو او هم داسې د فارس بادشاه داريوس په زمانه کښې د اِمامانو د کورَنو د مشرانو حِساب کِتاب ساتلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11672, 'Nehemiah 12:23', 'Nehemiah', 12, 23, '&nbsp;د اِلياسب نمسى د يوحانان وخت پورې د ليويانو د کورَنو مشرانو حِساب کِتاب د تاريخ په کِتاب کښې ليکلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11673, 'Nehemiah 12:24', 'Nehemiah', 12, 24, '&nbsp;دا د ليويانو د کورَنو مشران دى: حسبياه، سربياه، يشوَع، بِنوئى، قدمى‌اېل. په هغه وخت کښې به دوو ډلو يو بل ته مخامخ نمبر په نمبر د خُدائ پاک ثناء صِفت کولو او د هغۀ شُکر به يې ادا کولو. دا به يې د هغه اصُولو په مطابق کول کوم چې د خُدائ پاک خِدمت کوونکى داؤد بادشاه ورته ښودلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11674, 'Nehemiah 12:25', 'Nehemiah', 12, 25, '&nbsp;د خُدائ پاک د کور دا څوکيداران د خُدائ پاک د کور د دروازو سره د ګودامونو مشران وُو: متنياه، بقبوقياه، عبدياه، مسلام، طلمون او عقوب.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11675, 'Nehemiah 12:26', 'Nehemiah', 12, 26, '&nbsp;دا خلق د يوصدق نمسى او د يشوَع زوئ يويقيم په وخت کښې هلته اوسېدل او د نحمياه حکمران په وخت کښې او د عزرا په وخت کښې چې اِمام او د شريعت عالِم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11676, 'Nehemiah 12:27', 'Nehemiah', 12, 27, '&nbsp;کله چې د يروشلم د ښار دېوال وقف کېدلو، نو ليويان د هغه ټولو ځايونو نه راوستلے شول چرته چې هغوئ اوسېدل، هغوئ د دې دپاره راوستلے شول چې د وقف کېدو په جشن کښې د شُکر ګزارۍ د سندرو سره او د چمټو او بينجو د موسيقۍ سره شريک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11677, 'Nehemiah 12:28', 'Nehemiah', 12, 28, '&nbsp;د ليويانو کورَنو سندرغاړى د هغه علاقې نه راغونډ شول چرته چې هغوئ اوسېدل. هغوئ د يروشلم ګېرچاپېره علاقې نه او د نطوفه نه ګېرچاپېره د وړو ښارونو نه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11678, 'Nehemiah 12:29', 'Nehemiah', 12, 29, '&nbsp;او د بيت‌جِلجال، جبعه او عزماوت نه راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11679, 'Nehemiah 12:30', 'Nehemiah', 12, 30, '&nbsp;اِمامانو او ليويانو د خپلو ځانونو، خلقو، د دروازو او د ښار د دېوال دپاره د پاکوالى رسم ادا کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11680, 'Nehemiah 12:31', 'Nehemiah', 12, 31, '&nbsp;ما د دېوال دپاسه د يهوداه مشران راغونډ کړل او هغوئ مې د دوو لويو ډلو مشران مقرر کړل چې د ښار نه ګېرچاپېره روان شى او د خُدائ پاک شُکر ادا کوى. اوله ډله د دېوال دپاسه ښى طرف ته د ډېران دروازې طرف ته لاړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11681, 'Nehemiah 12:32', 'Nehemiah', 12, 32, '&nbsp;هوسعياه د سندرغاړو نه وروستو روان شو، چې د يهوداه نيم مشران ورپسې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11682, 'Nehemiah 12:36', 'Nehemiah', 12, 36, '&nbsp;په هغۀ پسې د هغۀ د قبيلې نور کسان وُو: سمعياه، عزراېل، مِللى، جِللى، ماعى، نتنى‌ايل، يهوداه او حنانى. هغوئ ټولو د موسيقۍ هغه شان څيزونه روان کړى وُو کوم چې د خُدائ پاک خِدمت کوونکى داؤد بادشاه غږول. عزرا عالِم د دې جلوس نه وړاندې روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11683, 'Nehemiah 12:37', 'Nehemiah', 12, 37, '&nbsp;د فوارې د دروازې سره هغوئ په هغه پوړو باندې وختل کومې چې د داؤد ښار ته تلې وې، د داؤد د محل نه تېر شول او د ښار نمرخاتۀ طرف ته د اوبو دروازې سره دېوال ته واپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11684, 'Nehemiah 12:38', 'Nehemiah', 12, 38, '&nbsp;د هغه کسانو بله ډله کومو چې شکريه ادا کوله د دېوال د سر سره ګس طرف ته لاړل او نيم خلق ما سره ورپسې روان وُو. مونږ د تنور د مينارې نه تېر شُو او پلن دېوال ته لاړُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11685, 'Nehemiah 12:39', 'Nehemiah', 12, 39, '&nbsp;او د هغه ځائ نه مونږ د اِفرائيم دروازې نه، يسانه دروازې نه، د کبانو دروازې نه، د حنن‌ايل مينارې او د سلو مينارې نه روان وُو او د ګډو دروازې ته لاړُو. او مونږ خپل تګ د خُدائ پاک د کور دروازې سره نزدې بس کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11686, 'Nehemiah 12:40', 'Nehemiah', 12, 40, '&nbsp;هغه دواړه ډلو کومو چې د خُدائ پاک شُکر ادا کولو هغه د خُدائ پاک د کور علاقې ته ورسېدلې. زۀ هم د مشرانو نيمې قبيلې سره وم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11687, 'Nehemiah 12:41', 'Nehemiah', 12, 41, '&nbsp;زما په ډله کښې دا اِمامان شامل وُو، چې هغوئ بيګلې غږولې: اِلياقيم، معسياه، مينامين، ميکاياه، اليوعينى، زکرياه او حننياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11688, 'Nehemiah 12:42', 'Nehemiah', 12, 42, '&nbsp;او په هغوئ پسې معسياه، سمعياه، اِلى‌عزر، عُزى، يهوحنان، مُلکياه، عيلام او ايصر روان وُو. د دې حمد ويوونکو مشرى ازرخياه کوله او په اوچت آواز يې سندرې وئيلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11689, 'Nehemiah 12:43', 'Nehemiah', 12, 43, '&nbsp;په هغه ورځ باندې ډېرې نذرانې پېش کړے شوې او د خلقو زړونه د خوشحالۍ نه ډک وُو ځکه چې خُدائ پاک هغوئ ډېر خوشحاله کړى وُو. ښځې او ماشومان په دې جشن کښې شريک وُو او چې هغوئ کوم شور جوړ کړے وو نو هغه تر لرې لرې پورې اورېدے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11690, 'Nehemiah 12:44', 'Nehemiah', 12, 44, '&nbsp;په هغه وخت کښې څۀ سړى د هغه ګودامونو مشران مقرر شوى وُو، چرته چې د خُدائ پاک د کور دپاره څيزونه کېښودلے شول، په دې کښې نذرانه، وړومبے پېدا شوې غله او لسمه حِصه. دا سړى د مختلفو ښارونو سره نزدې پټو نه د برخو راغونډولو ذمه وار وُو. دا برخې د قانون په مطابق د اِمامانو او ليويانو دپاره وې. د يهوداه ټول خلق د اِمامانو او ليويانو نه خوشحاله وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11691, 'Nehemiah 12:45', 'Nehemiah', 12, 45, '&nbsp;هغوئ د پاکوالى رسمونه او هغه نور رسمونه ادا کول د کومو چې خُدائ پاک حُکم ورکړے وو. د خُدائ پاک د کور موسيقارانو او څوکيدارانو هم خپله ذمه وارى د هغه اصُولو په مطابق سر ته رسوله کوم چې داؤد بادشاه او د هغۀ زوئ سليمان جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11692, 'Nehemiah 12:46', 'Nehemiah', 12, 46, '&nbsp;ډېر وخت مخکښې د داؤد بادشاه او آسف موسيقار د وخت، موسيقارانو د خُدائ پاک د ثناء صِفت کولو او د شُکر ګزارۍ مشرى کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11693, 'Nehemiah 12:47', 'Nehemiah', 12, 47, '&nbsp;د زرُبابل او نحمياه په زمانه کښې به ټولو بنى اِسرائيلو هره ورځ د خُدائ د کور د سندرغاړو او څوکيدارانو ضرورتونه پوره کول. ليويانو ته به هغه برخه ورکولے کېدله کومه چې هغوئ دپاره مقرر وه او ليويانو به د هغې نه اِمامانو له هغه برخه ورکوله کومه چې د هغوئ دپاره مقرر وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11694, 'Nehemiah 13:1', 'Nehemiah', 13, 1, '&nbsp;کله چې د موسىٰ شريعت خلقو ته په اوچت آواز لوستلے شو، نو هغوئ دې آياتونو ته راغلل چې وائ، يو عمونى او موآبى ته به هم دا اجازت نۀ وى چې د خُدائ پاک په ډله کښې داخل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11695, 'Nehemiah 13:2', 'Nehemiah', 13, 2, '&nbsp;دا د هغې په وجه کله چې بنى اِسرائيل د مِصر نه بهر په لار روان وُو نو عمونيانو او موآبيانو هغوئ له اوبۀ او روټۍ نۀ وه ورکړې. او د دې په ځائ بلعام له يې پېسې ورکړې چې په بنى اِسرائيلو باندې لعنت ووائى، خو زمونږ خُدائ پاک هغه لعنت په برکت بدل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11696, 'Nehemiah 13:3', 'Nehemiah', 13, 3, '&nbsp;کله چې بنى اِسرائيلو دا حُکم واورېدو نو هغوئ د قوم نه د پردى مُلک ټول خلق وويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11697, 'Nehemiah 13:4', 'Nehemiah', 13, 4, '&nbsp;اِلياسب اِمام کوم چې د خُدائ پاک د ګودامونو مشر وو، هغه د ډېرې مودې نه د طوبياه ملګرے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11698, 'Nehemiah 13:5', 'Nehemiah', 13, 5, '&nbsp;هغۀ طوبياه له دا اجازت ورکړو چې يوه لويه کوټه استعمالوى چې به مخکښې په کښې د غلې نذرانو او خوشبويۍ نذرانو د جمع کولو او د خُدائ پاک په کور کښې د استعمالېدونکى سامان دپاره، د اِمامانو د نذرانو دپاره، د غلې د لسمې حصې، د ميو او د زيتُونو هغه تېلو دپاره مخصوصه وه کومه به چې ليويانو، د خُدائ پاک د کور موسيقارانو او د خُدائ پاک د کور څوکيدارانو دپاره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11699, 'Nehemiah 13:6', 'Nehemiah', 13, 6, '&nbsp;کله چې داسې کېدل، نو زۀ په يروشلم کښې نۀ وم، ځکه چې د بابل بادشاه ارتخششتا د بادشاهۍ په دوه دېرشم کال زۀ هغۀ له واپس ورغلے وم چې خبر ورورسوم. څۀ وخت وروستو ما ته د هغۀ نه اجازت مِلاو شو چې واپس يروشلم ته تلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11700, 'Nehemiah 13:7', 'Nehemiah', 13, 7, '&nbsp;کله چې يروشلم ته راواپس شوم نو ما ته د دې بدعملۍ پته ولګېده چې اِلياسب طوبياه له اجازت ورکړے دے چې د خُدائ پاک په کور کښې يوه کوټه استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');